import type { CartModel } from '@/cart/data/models';

type FreeGiftLineItem = Pick<
  CartModel['items'][number],
  'price' | 'regularPrice' | 'originalItemPrice' | 'quantity'
>;

/**
 * Unit amount shown for free-gift lines: line price when set (e.g. catalog special),
 * otherwise catalog `original_item_price` (reflects catalog special price; unlike
 * `regularPrice`, which is the full catalog price for configurable items and would
 * overstate the struck-through amount), falling back to `regularPrice` when unset.
 */
export function getFreeGiftDisplayUnit(item: FreeGiftLineItem): {
  value: number;
  currency: string;
} {
  const lineUnit = item.price?.value ?? 0;
  if (lineUnit > 0) {
    return {
      value: lineUnit,
      currency: item.price?.currency ?? item.regularPrice?.currency ?? 'USD',
    };
  }

  const catalogSpecial = item.originalItemPrice?.value ?? 0;
  if (catalogSpecial > 0) {
    return {
      value: catalogSpecial,
      currency:
        item.originalItemPrice?.currency ??
        item.regularPrice?.currency ??
        'USD',
    };
  }

  const catalogOriginal = item.regularPrice?.value ?? 0;
  if (catalogOriginal > 0) {
    return {
      value: catalogOriginal,
      currency: item.regularPrice?.currency ?? item.price?.currency ?? 'USD',
    };
  }

  return {
    value: 0,
    currency: item.price?.currency ?? item.regularPrice?.currency ?? 'USD',
  };
}

/** Row strike total for free-gift lines (display unit × quantity). */
export function getFreeGiftLineStrikeTotal(item: FreeGiftLineItem): {
  value: number;
  currency: string;
} {
  const unit = getFreeGiftDisplayUnit(item);
  const qty = item.quantity ?? 1;
  return {
    value: unit.value * qty,
    currency: unit.currency,
  };
}
