import { CartModel } from '@/cart/data/models';
import { decodeHTMLEntities } from '@/cart/lib/decodeHTMLEntities';

type BackorderTextItem = Pick<
  CartModel['items'][number],
  'backorderMessage' | 'insufficientQuantity' | 'outOfStock'
>;

export function getBackorderText(item: BackorderTextItem): string | undefined {
  if (!item.backorderMessage || item.insufficientQuantity || item.outOfStock) {
    return undefined;
  }

  return decodeHTMLEntities(item.backorderMessage);
}
